if(getenv('ESTRABAO_SYNTHETIC_LAB')!=='1'){exit(1);}chdir('/var/www/html');$c=parse_ini_file('config.inc.php',true);if((($c['database']['name']??'')!=='estrabao_synthetic'||($c['database']['host']??'')!=='estrabao-lab-62-restore-db')||($c['general']['base_url']??'')!=='http://127.0.0.1:18080'){exit(1);}require 'tools/bootstrap.inc.php';new CommandLineTool([]);
