 $journal->setData('supportedSubmissionLocales',['pt_BR','en_US','es_ES']);$journal->setData('citations',1);$journal->setData('keywords',1);$journal->setData('agencies',1);$journal->setData('supportedFormLocales',['pt_BR','en_US','es_ES']);Application::getContextDAO()->updateObject($journal);
